INSERT INTO `sys_cms_content` VALUES (7, 'System_Guide', '系统概况', '系统首页概况说明', '<table style=\"width: auto; text-align: start;\"><tbody><tr><th colspan=\"1\" rowspan=\"1\" width=\"68\" style=\"text-align: left;\"><strong>系统名</strong>称</th><th colspan=\"0\" rowspan=\"1\" width=\"auto\" style=\"text-align: left;\">h-boot-admin管理系统</th></tr><tr><td colspan=\"1\" rowspan=\"1\" width=\"auto\" style=\"text-align: left;\"><strong>版本号</strong></td><td colspan=\"0\" rowspan=\"1\" width=\"auto\" style=\"text-align: left;\">v1.0.0</td></tr><tr><td colspan=\"1\" rowspan=\"1\" width=\"auto\" style=\"text-align: left;\"><strong>后端框架</strong></td><td colspan=\"0\" rowspan=\"1\" width=\"auto\" style=\"text-align: left;\">Spring Boot 3 + Spring Security 6 + JWT</td></tr><tr><td colspan=\"1\" rowspan=\"1\" width=\"auto\" style=\"text-align: left;\"><strong>前端框架</strong></td><td colspan=\"0\" rowspan=\"1\" width=\"auto\" style=\"text-align: left;\">Vue3 + Vite + Element Plus +TypeScript + Pinia</td></tr></tbody></table><p><br></p>', 1, 1, 0, '2026-01-01 19:28:35', 'admin', '2026-01-01 19:28:35', '2026-01-01 21:40:03');
